    "Prevalence: topic items / eligible items in a platform’s declared window. Velocity: change in that share, in standard deviations against that platform’s prior windows. Source mix: source families with usable coverage / six planned families. The displayed values are illustrative, not measured.": [
      "话题占比：在平台声明的时间窗内，话题条目数占符合条件条目数的比例。变化速率：该占比相对平台此前时间窗的变化，以标准差表示。来源组合：具备有效覆盖的来源类别数 / 计划中的六类来源。显示值均为示意值，并非实测。",
      "出現比率は、プラットフォームごとに定めた期間内の対象項目に占める話題項目の割合です。変化速度は、その割合の変化を過去の期間に対する標準偏差で表します。情報源の構成は、利用可能な情報源の種類数を予定する6種類で割った値です。表示値は例示であり、実測値ではありません。",
      "주제 비중은 플랫폼별로 정한 기간의 적격 항목 중 해당 주제 항목의 비율입니다. 변화 속도는 그 비율의 변화를 이전 기간 대비 표준편차로 나타냅니다. 출처 구성은 활용 가능한 출처 유형 수를 계획된 6개 유형으로 나눈 값입니다. 표시된 값은 실측값이 아닌 예시입니다."
    ],
    "Notice share counts markers beyond reachable. Return and commitment are separate final-stage shares. Source HHI is the sum of squared platform shares; higher means a more concentrated platform mix. Readout values describe the 72-hour example, not the current playback hour.": [
      "注意占比统计已超出“可触达”阶段的标记。回访与行动占比分别对应各自的最终阶段。来源 HHI 为各平台占比平方和，数值越高，平台分布越集中。读数描述 72 小时示例结果，而非当前播放时刻。",
      "注目率は「接触可能」の次の段階に進んだマーカーの割合です。再訪率と行動率は、それぞれ最終段階の別個の割合を示します。情報源HHIは各プラットフォームの構成比の二乗和で、高いほど集中しています。数値は現在の再生時刻ではなく、72時間の例を表します。",
      "주목 비율은 도달 가능 단계를 넘어선 마커의 비율입니다. 재방문과 행동 이행은 각각 별도의 최종 단계 비율입니다. 출처 HHI는 플랫폼별 비중의 제곱합이며, 높을수록 특정 플랫폼에 집중되어 있습니다. 표시값은 현재 재생 시점이 아니라 72시간 예시의 결과입니다."
    ],
