      "同意を得た集団属性、事前に定義した交差集団、欠損、標本数、誤差、校正、被覆率、棄権、処置効果。",
      "동의받은 집단 속성, 사전 정의된 교차집단, 결측, 표본 크기, 오차, 보정, 포함률, 예측 유보, 처치 효과."
